import React, { useState } from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const VendorsPage: React.FC = () => {
  const [vendorData, setVendorData] = useState({
    vendorName: "",
    vendorType: "",
    description: "",
    pricing: "",
    instagramLink: "",
    website: "",
    phone: "",
    email: "",
    availableDates: [] as string[], // Store dates as strings
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setVendorData({ ...vendorData, [e.target.name]: e.target.value });
  };

  const handleDateChange = (date: Date | null) => {
    if (!date) return;

    setVendorData((prevData) => {
      const formattedDate = date.toISOString().split("T")[0];
      const updatedDates = prevData.availableDates.includes(formattedDate)
        ? prevData.availableDates.filter((d) => d !== formattedDate)
        : [...prevData.availableDates, formattedDate];

      return { ...prevData, availableDates: updatedDates };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const response = await fetch("http://localhost:5000/vendors", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(vendorData),
      });

      if (response.ok) {
        setSuccessMessage("Vendor added successfully!");
        setVendorData({
          vendorName: "",
          vendorType: "",
          description: "",
          pricing: "",
          instagramLink: "",
          website: "",
          phone: "",
          email: "",
          availableDates: [],
        });
      } else {
        const errorData = await response.json();
        setError(errorData.message || "Failed to add vendor.");
      }
    } catch (error) {
      setError("An error occurred.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Vendor Registration</h2>
      {error && <p style={{ color: "red" }}>{error}</p>}
      {successMessage && <p style={{ color: "green" }}>{successMessage}</p>}
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="vendorName"
          value={vendorData.vendorName}
          onChange={handleChange}
          placeholder="Vendor Name"
          required
        />
        <select
          name="vendorType"
          value={vendorData.vendorType}
          onChange={handleChange}
          required
        >
          <option value="">Select Vendor Type</option>
          <option value="Caterer">Caterer</option>
          <option value="Photographer">Photographer</option>
          <option value="Venue">Venue</option>
          <option value="Florist">Florist</option>
        </select>
        <textarea
          name="description"
          value={vendorData.description}
          onChange={handleChange}
          placeholder="Description"
        />
        <input
          type="text"
          name="pricing"
          value={vendorData.pricing}
          onChange={handleChange}
          placeholder="Pricing"
        />
        <input
          type="text"
          name="instagramLink"
          value={vendorData.instagramLink}
          onChange={handleChange}
          placeholder="Instagram Link"
        />
        <input
          type="text"
          name="website"
          value={vendorData.website}
          onChange={handleChange}
          placeholder="Website"
        />
        <input
          type="text"
          name="phone"
          value={vendorData.phone}
          onChange={handleChange}
          placeholder="Phone"
        />
        <input
          type="email"
          name="email"
          value={vendorData.email}
          onChange={handleChange}
          placeholder="Email"
        />
        <DatePicker
          selected={null}
          onChange={handleDateChange}
          placeholderText="Select Available Date"
          dateFormat="yyyy-MM-dd"
        />
        <button type="submit" disabled={loading}>
          {loading ? "Submitting..." : "Submit"}
        </button>
      </form>
    </div>
  );
};

export default VendorsPage;


